      <div class="col-md-3"><button class="btn btn-primary w-100" type="submit" data-confirm="تعيين الهيكل لكل طلاب الشعبة غير المعيَّنين؟">تعيين</button></div></form>
      <?php if (!$s['assigned']): ?><button class="btn btn-sm btn-outline-danger mt-2" data-api="<?= url('api/v1/school/fees/structures/' . (int)$s['id']) ?>" data-method="DELETE" data-confirm="حذف الهيكل؟">حذف</button><?php endif; ?><?php endif; ?></div><?php endforeach; ?></div>
  <?php if ($can): ?><div class="col-xl-5"><form class="card-s" id="structForm" data-url="<?= url('api/v1/school/fees/structures') ?>"><?= csrf_field() ?><h2 class="h6">هيكل رسوم جديد</h2>
    <div class="mb-2"><label class="form-label" for="sname">الاسم</label><input class="form-control" id="sname" name="name" placeholder="مثال: رسوم الصف الأول 2026/2027" required></div>
    <div class="row g-2 mb-2"><div class="col-6"><label class="form-label" for="syear">السنة</label><select class="form-select" id="syear" name="academic_year_id"><?php foreach ($years as $y): if ($y['status'] === 'closed') continue; ?><option value="<?= (int)$y['id'] ?>" <?= $activeYear && (int)$activeYear['id'] === (int)$y['id'] ? 'selected' : '' ?>><?= e($y['name']) ?></option><?php endforeach; ?></select></div>
      <div class="col-6"><label class="form-label" for="sgrade">الصف</label><select class="form-select" id="sgrade" name="grade_level_id"><option value="">كل الصفوف</option><?php foreach ($grades as $g): ?><option value="<?= (int)$g['id'] ?>"><?= e($g['name']) ?></option><?php endforeach; ?></select></div>
